   201|export function parseStructuredSystemMessage(body: string | null | undefined): Array<{ label: string; value: string }> | null {
   202|  const lines = body?.split('\n').map((line) => line.trim()).filter((line) => line.length > 0) ?? [];
   203|  const rows = lines
   204|    .map((line) => {
   205|      const separatorIndex = line.indexOf(':');
   206|      if (separatorIndex <= 0) {
   207|        return null;
   208|      }
   209|      const label = line.slice(0, separatorIndex).trim();
   210|      const value = line.slice(separatorIndex + 1).trim();
   211|      if (!label || !value) {
   212|        return null;
   213|      }
   214|      return { label, value };
   215|    })
   216|    .filter((row): row is { label: string; value: string } => row !== null);
   217|
   218|  if (rows.length < 3) {
   219|    return null;
   220|  }
   221|
   222|  return rows.some((row) => row.label.toLowerCase() === 'result') && rows.some((row) => row.label.toLowerCase() === 'evidence')
   223|    ? rows
   224|    : null;
